<script type="application/ld+json">{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое ФНН простыми словами?", "acceptedAnswer": {"@type": "Answer", "text": "Это уникальный тринадцатиразрядный номер конкретного изделия в федеральном каталоге продукции для федеральных нужд. По нему заказчик, головной исполнитель и исполнитель понимают, что речь об одном и том же предмете снабжения, даже если в разных документах он называется по-разному."}}, {"@type": "Question", "name": "Кто присваивает федеральный номенклатурный номер?", "acceptedAnswer": {"@type": "Answer", "text": "Центр каталогизации государственного заказчика — по предметам снабжения из утверждённого номенклатурного перечня (подпункт «в» пункта 14 Правил). По комплектующим изделиям и материалам военного назначения номера присваивает центр каталогизации по закреплённым группам однородной продукции (подпункт «в» пункта 15). Диапазоны номеров между центрами распределяет федеральный центр каталогизации."}}, {"@type": "Question", "name": "Обязана ли компания заниматься каталогизацией?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если она головной исполнитель или исполнитель по гособоронзаказу. Часть 8 статьи 6.1-1 закона № 275-ФЗ обязывает обеспечивать полноту, достоверность и актуальность информации о товарах, подлежащих каталогизации, и своевременность её размещения в каталоге. Конкретные действия перечислены в пункте 18 Правил."}}, {"@type": "Question", "name": "Сколько ждать присвоения номера?", "acceptedAnswer": {"@type": "Answer", "text": "Центр каталогизации государственного заказчика рассматривает размещённые документы в течение 15 рабочих дней. При отказе на доработку даётся не более 15 рабочих дней, повторное рассмотрение — 10 рабочих дней. Полный цикл с одним отказом — до 40 рабочих дней."}}, {"@type": "Question", "name": "По какой причине могут отказать?", "acceptedAnswer": {"@type": "Answer", "text": "Основание одно: номенклатурные перечни и каталожные описания не соответствуют требованиям пунктов 32 и 33 Правил, то есть требованиям ГОСТ РВ 0044-014-2012 и ГОСТ РВ 0044-007-2019. Заключение об отказе направляется с указанием причины."}}, {"@type": "Question", "name": "Нужно ли каталогизировать изделие повторно при новом контракте?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Если предметам снабжения ранее присвоены федеральные номенклатурные номера, исполнитель размещает уведомление об использовании ранее присвоенных номеров в отношении идентичных предметов снабжения, а центр каталогизации информирует его о наличии номеров (пункты 37 и 41 Правил)."}}, {"@type": "Question", "name": "Что делать, если изменилась техническая документация?", "acceptedAnswer": {"@type": "Answer", "text": "Разместить номенклатурные перечни и каталожные описания повторно — в порядке и сроки пункта 37. Это прямо предусмотрено пунктом 38 Правил и относится также к случаю изменения условий контракта."}}, {"@type": "Question", "name": "Чем ФНН отличается от ИГК?", "acceptedAnswer": {"@type": "Answer", "text": "ФНН идентифицирует изделие, ИГК — государственный контракт. Идентификатор государственного контракта указывается в платёжных и первичных документах и обеспечивает адресность расчётов по контракту, федеральный номенклатурный номер к расчётам отношения не имеет."}}, {"@type": "Question", "name": "Кто оплачивает работы по каталогизации?", "acceptedAnswer": {"@type": "Answer", "text": "По предметам снабжения — в соответствии с заключёнными контрактами за счёт средств федерального бюджета, предусмотренных на эти цели в государственных программах, федеральных целевых программах и государственной программе вооружения. Инициативная подготовка описаний комплектующих изделий и материалов военного назначения по пункту 19 Правил — за счёт собственных средств исполнителя."}}, {"@type": "Question", "name": "Можно ли поручить подготовку описаний сторонней организации?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Пункт 20 Правил позволяет головным исполнителям, исполнителям и центрам каталогизации по группам привлекать российских юридических лиц для подготовки каталожных описаний. Ответственность за достоверность сведений остаётся на исполнителе."}}, {"@type": "Question", "name": "Есть ли продукция, которую в каталог не размещают?", "acceptedAnswer": {"@type": "Answer", "text": "Да. С 4 августа 2026 года часть 10 статьи 6.1-1 закона № 275-ФЗ выводит из-под размещения информацию о товарах, поставляемых для органов внешней разведки, органов федеральной службы безопасности и для работ Госкорпорации «Росатом» с ядерными боеприпасами и ядерными зарядами."}}, {"@type": "Question", "name": "Где посмотреть действующую редакцию Правил?", "acceptedAnswer": {"@type": "Answer", "text": "Постановление Правительства РФ от 27.04.2024 № 549 действует в редакции постановления от 29.07.2026 № 949 с 7 августа 2026 года. Материалы, описывающие первоначальную редакцию 2024 года, устарели на две правки."}}]}</script>
<script type="application/ld+json">{"@context": "https://schema.org", "@type": "HowTo", "name": "Как исполнителю гособоронзаказа получить федеральный номенклатурный номер", "totalTime": "P15D", "step": [{"@type": "HowToStep", "name": "Определить предметы каталогизации", "text": "На основании заключённого государственного контракта определить предметы снабжения, подлежащие каталогизации, а также комплектующие изделия и материалы военного назначения (пункты 18 и 19 Правил)."}, {"@type": "HowToStep", "name": "Подготовить номенклатурный перечень", "text": "Составить номенклатурный перечень предметов снабжения по требованиям ГОСТ РВ 0044-014-2012 (пункт 32 Правил)."}, {"@type": "HowToStep", "name": "Подготовить каталожные описания", "text": "Составить каталожные описания по требованиям ГОСТ РВ 0044-007-2019 и включить их в техническую документацию (пункты 30 и 33 Правил)."}, {"@type": "HowToStep", "name": "Утвердить описания", "text": "Утвердить каталожные описания по предметам заключённого контракта; по комплектующим изделиям и материалам военного назначения описания утверждает центр каталогизации по закреплённым группам однородной продукции."}, {"@type": "HowToStep", "name": "Разместить документы в системе", "text": "Однократно в течение срока действия контракта разместить номенклатурные перечни и каталожные описания с использованием информационных технологий каталогизации, а при их отсутствии — на электронных носителях (пункт 37 Правил)."}, {"@type": "HowToStep", "name": "Дождаться рассмотрения", "text": "Центр каталогизации государственного заказчика рассматривает документы в течение 15 рабочих дней со дня размещения (пункт 39 Правил)."}, {"@type": "HowToStep", "name": "Получить и применять номер", "text": "При соответствии требованиям сведения включаются в федеральный каталог и предметам снабжения присваиваются федеральные номенклатурные номера; с даты присвоения информация каталога применяется обязательно (пункты 40 и 49 Правил)."}]}</script>
